import sys
from collections import deque

def main():
    input = sys.stdin.read().splitlines()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        ptr += 1
        C = input[ptr]
        ptr += 1
        adj = [[] for _ in range(N+1)]
        for __ in range(N-1):
            u, v = map(int, input[ptr].split())
            adj[u].append(v)
            adj[v].append(u)
            ptr += 1

        blue = []
        for i in range(1, N+1):
            if C[i-1] == 'B':
                blue.append(i)

        if len(blue) < 2:
            print("Yes")
            continue

        parent = [0]*(N+1)
        depth = [0]*(N+1)
        visited = [False]*(N+1)
        q = deque()
        q.append(1)
        visited[1] = True
        while q:
            u = q.popleft()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    depth[v] = depth[u] + 1
                    q.append(v)

        def lca(u, v):
            while u != v:
                if depth[u] > depth[v]:
                    u = parent[u]
                else:
                    v = parent[v]
            return u

        def get_path(u, v):
            path_u = []
            path_v = []
            while u != v:
                if depth[u] >= depth[v]:
                    path_u.append(u)
                    u = parent[u]
                else:
                    path_v.append(v)
                    v = parent[v]
            path_u.append(u)
            path_v.reverse()
            return path_u + path_v

        valid = True
        for i in range(len(blue)):
            for j in range(i+1, len(blue)):
                u = blue[i]
                v = blue[j]
                path = get_path(u, v)
                has_R = False
                has_G = False
                for node in path:
                    if C[node-1] == 'R':
                        has_R = True
                    if C[node-1] == 'G':
                        has_G = True
                if not (has_R and has_G):
                    valid = False
                    break
            if not valid:
                break
        print("Yes" if valid else "No")

main()
